SELECT r.id, r.integration_id, r.slack_channel_id, r.slack_thread_root_message_id, r.backend_conversation_id, r.gateway_access_mode, r.backend_principal_id, r.gateway_binding_owner_id, r.gateway_binding_state, r.backend_protocol_messages, r.backend_protocol_state, r.created_at, r.updated_at, r.last_activity_at, r.closed_at FROM conversation_binding r WHERE $criteria.CompositeIn("r", $WriterKeys)